import {
    Group,
    Mesh,
    PlaneGeometry,
    SphereGeometry,
    CylinderGeometry,
    Box3,
    Vector3,
    MeshStandardNodeMaterial,
    MeshPhysicalNodeMaterial,
    MeshBasicNodeMaterial,
} from 'three/webgpu';
import { color, mix, uv, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';
import { orbit as orbitPrimitive } from '@/primitives';

export default function createNode(config, ctx) {
    const root = new Group();

    // ---------- Backdrop with gradient ----------
    const backdropGeom = new PlaneGeometry(7, 6);
    const backdropMat = new MeshBasicNodeMaterial();
    const gradTop = color('#0b0b10');
    const gradMid = color('#101017');
    const gradBot = color('#16161d');
    const uvY = uv().y;
    const firstMix = mix(gradTop, gradMid, smoothstep(0.0, 0.65, uvY));
    backdropMat.colorNode = mix(firstMix, gradBot, smoothstep(0.65, 1.0, uvY));
    const backdrop = new Mesh(backdropGeom, backdropMat);
    backdrop.position.set(0, 0, -3);
    root.add(backdrop);

    // ---------- Contact shadow ----------
    const shadowGeom = new PlaneGeometry(2.6, 1.2);
    const shadowMat = new MeshBasicNodeMaterial();
    shadowMat.colorNode = color('#000000');
    shadowMat.transparent = true;
    shadowMat.opacity = 0.5;
    const shadow = new Mesh(shadowGeom, shadowMat);
    shadow.rotation.x = -Math.PI / 2;
    shadow.position.set(0, -1.2, 0);
    root.add(shadow);

    // ---------- Jewel pivot ----------
    const jewelGeom = new SphereGeometry(0.12, 32, 32);
    const jewelMat = new MeshPhysicalNodeMaterial();
    jewelMat.colorNode = color('#ff2a38');
    jewelMat.transmission = 0.6;
    jewelMat.ior = 1.76;
    jewelMat.emissiveNode = color('#ff2a38');
    jewelMat.emissiveIntensity = 1.8;
    const jewel = new Mesh(jewelGeom, jewelMat);
    jewel.position.set(0, 0, 0);
    root.add(jewel);

    // ---------- Arbor shaft ----------
    const shaftGeom = new CylinderGeometry(0.05, 0.05, 0.8, 16);
    const shaftMat = new MeshStandardNodeMaterial();
    shaftMat.colorNode = color('#16161d');
    shaftMat.metalness = 0;
    shaftMat.roughness = 0.8;
    const shaft = new Mesh(shaftGeom, shaftMat);
    shaft.rotation.x = Math.PI / 2;
    shaft.position.set(0, 0, 0);
    root.add(shaft);

    // ---------- Text ----------
    const texts = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
    for (const item of texts) {
        const opts = {
            fontSize: item.typography?.fontSize,
            color: '#e8ecf2',
            align: 'center',
        };
        const txtObj = ctx.fontAtlas.createText(item.text ?? '', opts);
        if (item.role === 'headline') {
            txtObj.position.set(0, -1.7, 0);
        } else if (item.role === 'caption') {
            txtObj.position.set(0, -2.1, 0);
        }
        root.add(txtObj);
    }

    // ---------- Load GLB ----------
    const disposables = [];
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
        const model = gltf.scene.clone();
        root.add(model);

        // Find first mesh as primary gear
        let primaryGear = null;
        model.traverse((obj) => {
            if (obj.isMesh && !primaryGear) {
                primaryGear = obj;
            }
        });

        if (!primaryGear) return;

        // Gear material (steel)
        const gearMat = new MeshStandardNodeMaterial();
        gearMat.metalness = 0.55;
        gearMat.roughness = 0.5;
        gearMat.clearcoat = 0.2;
        gearMat.clearcoatRoughness = 0.3;
        gearMat.anisotropy = 0.7;
        gearMat.colorNode = color('#777777');
        primaryGear.material = gearMat;
        disposables.push(gearMat);

        // Compute primary gear diameter for proper scaling
        const bbox = new Box3().setFromObject(primaryGear);
        const size = new Vector3();
        bbox.getSize(size);
        const primaryDiameter = Math.max(size.x, size.y);

        // Secondary gear clone
        const secondaryGear = primaryGear.clone();
        const desiredDiameter = 0.9;
        const scaleFactor = desiredDiameter / primaryDiameter;
        secondaryGear.scale.setScalar(scaleFactor);
        secondaryGear.position.set(1.15, 0.35, -0.1);
        secondaryGear.rotation.z = Math.PI; // opposite direction
        const secondaryMat = gearMat.clone();
        secondaryGear.material = secondaryMat;
        disposables.push(secondaryMat);
        root.add(secondaryGear);

        // Rotation timelines for meshing motion
        const primaryDuration = (2 * Math.PI) / 0.08; // rad/s
        const secondaryDuration = (2 * Math.PI) / 0.142; // rad/s opposite

        const rotTimeline = gsap.timeline({ repeat: -1 });
        rotTimeline.to(
            primaryGear.rotation,
            { z: `+=${2 * Math.PI}`, duration: primaryDuration, ease: 'none' },
            0
        );
        rotTimeline.to(
            secondaryGear.rotation,
            { z: `-=${2 * Math.PI}`, duration: secondaryDuration, ease: 'none' },
            0
        );

        disposables.push({
            kill() {
                rotTimeline.kill();
            },
        });
    });

    // ---------- Cinematic primitives ----------
    const primitiveCleanups = [];
    if (Array.isArray(config.cinematicPrimitives)) {
        for (const prim of config.cinematicPrimitives) {
            if (prim.name && ctx.primitives[prim.name]) {
                const result = ctx.primitives[prim.name](root, prim.params || {});
                if (result?.cleanup) primitiveCleanups.push(result.cleanup);
                if (result?.timeline) {
                    disposables.push({
                        kill() {
                            result.timeline.kill?.();
                        },
                    });
                }
            }
        }
    }

    // ---------- Ensure orbit primitive ----------
    if (!config.cinematicPrimitives?.some((p) => p.name === 'orbit')) {
        const result = orbitPrimitive(root, { speed: 0.08, radius: 0.2 });
        if (result?.cleanup) primitiveCleanups.push(result.cleanup);
    }

    // ---------- Cleanup ----------
    root.userData.handlers = {};

    root.userData.cleanup = () => {
        // Dispose custom geometries and materials
        backdropGeom.dispose();
        shadowGeom.dispose();
        jewelGeom.dispose();
        shaftGeom.dispose();

        backdropMat.dispose();
        shadowMat.dispose();
        jewelMat.dispose();
        shaftMat.dispose();

        // Dispose other disposables
        for (const d of disposables) {
            if (typeof d.dispose === 'function') d.dispose();
            else if (typeof d.kill === 'function') d.kill();
        }

        // Primitive cleanups
        for (const fn of primitiveCleanups) {
            try {
                fn();
            } catch (_) {}
        }

        // Dispose GLTF children
        root.traverse((obj) => {
            if (obj.isMesh) {
                obj.geometry?.dispose?.();
                obj.material?.dispose?.();
            }
        });
    };

    return root;
}
